// Règles de qualification déterministes et explicables (adaptables à toute niche)
const items = $input.all();
const results = [];

for (const item of items) {
  const lead = item.json.body || item.json;

  let score = 0;
  const justifications = [];

  // 1. Canal de contact direct
  if (lead.telephone && (lead.telephone.startsWith('+225') || lead.telephone.length >= 10)) {
    score += 30;
    justifications.push('Numéro WhatsApp/téléphone local disponible (+30)');
  } else if (lead.email) {
    score += 15;
    justifications.push('Email professionnel/direct fourni (+15)');
  }

  // 2. Activité et Entreprise identifiées
  if (lead.nom_entreprise && lead.nom_entreprise.length > 2) {
    score += 25;
    justifications.push('Nom d\'entreprise/boutique clairement identifié (+25)');
  }

  // 3. Besoin exprimé
  if (lead.besoin_exprime && lead.besoin_exprime.length > 10) {
    score += 30;
    justifications.push('Besoin commercial/organisationnel formulé (+30)');
  } else {
    score += 10;
    justifications.push('Activité déclarée sans besoin précis explicite (+10)');
  }

  // 4. Localisation
  if (lead.ville && lead.ville.toLowerCase().includes('abidjan')) {
    score += 15;
    justifications.push('Zone géographique prioritaire (+15)');
  } else {
    score += 5;
    justifications.push('Autre zone couverte (+5)');
  }

  // Vérification stricte de l'exclusion
  const ne_plus_contacter = Boolean(lead.ne_plus_contacter);
  const statut_crm = ne_plus_contacter ? 'ne_plus_contacter' : (score >= 50 ? 'qualifie' : 'a_evaluer');

  results.push({
    json: {
      ...lead,
      score_qualification: score,
      justification_score: justifications.join(' | '),
      statut_crm,
      pret_pour_brouillon: !ne_plus_contacter && score >= 50
    }
  });
}

return results;

// Génération sécurisée du brouillon d'approche personnalisé sans hallucination
// Ce bloc prépare le contexte et le texte d'accroche personnalisé selon la niche fournie
const item = $input.item;
const lead = item.json;

const interlocuteur = lead.nom_contact ? lead.nom_contact : 'l\'équipe de ' + lead.nom_entreprise;
const secteur = lead.secteur_activite && lead.secteur_activite !== 'Non spécifié' ? lead.secteur_activite : 'votre activité';
const besoin = lead.besoin_exprime ? `concernant "${lead.besoin_exprime}"` : 'sur l\'optimisation de vos échanges clients';

const brouillon_message = `Bonjour ${interlocuteur},

Je suis l'équipe Digisys. Nous accompagnons les professionnels dans le secteur (${secteur}) à Abidjan pour simplifier le suivi de leurs commandes et demandes clients sur WhatsApp et les réseaux sociaux.

Suite à votre intérêt ${besoin}, nous avons préparé une approche simple et adaptée à votre organisation.

Seriez-vous disponible pour un court échange de 10 minutes cette semaine ?

Bien cordialement,
L'équipe Digisys`;

return {
  json: {
    ...lead,
    brouillon_message,
    statut_crm: 'brouillon_a_valider',
    date_generation_brouillon: new Date().toISOString()
  }
};

